const payload = $json.body || $json;
const now = new Date().toISOString();
return [{
  json: {
    workflow_execution_id: payload.workflow_execution_id || $execution.id,
    session_id: (payload.session_id || `sgs_${Date.now()}`).toString(),
    customer_id: (payload.customer_id || '').toString(),
    channel: (payload.channel || 'web').toString(),
+    message: (payload.message || '').toString().trim(),
    language: ((payload.language || payload.lang || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es',
    conversation_stage: (payload.conversation_stage || '').toString(),
    current_service: (payload.current_service || payload.service || 'general').toString(),
    pending_action: (payload.pending_action || '').toString(),
    collected_fields: payload.collected_fields || {},
    recent_messages: Array.isArray(payload.recent_messages) ? payload.recent_messages : [],
    session_state: payload.session_state || {},
    sessionApi: !!(payload.sessionApiEnabled || payload.sessionApi),
    loggerEnabled: !!(payload.loggerEnabled || payload.logEnabled || false),
    startAt: now
  }
}];

const p = $json;
return [{
  json: {
    model: ($env.SGS_QWEN_CLASSIFIER_MODEL || 'qwen3-14b').toString(),
    messages: [
      {
        role: 'system',
        content: 'You are the intent classifier for SG Solutions. Return ONLY valid JSON that matches the schema. Never include markdown, notes, or explanations.'
      },
      {
        role: 'user',
        content: 'Classify user intent for SG Solutions support.

Return JSON with:
{
  "language": "es|en",
  "intent": "GREETING|GENERAL_QUESTION|SERVICE_INFORMATION|SERVICE_RECOMMENDATION|PRICING_QUESTION|CREDIT_SERVICE|TAX_SERVICE|BUSINESS_FORMATION|BUSINESS_FUNDING|LOAN_PREPARATION|HOME_BUYING|DOCUMENT_REQUIREMENTS|APPOINTMENT_REQUEST|CHECK_AVAILABILITY|BOOK_APPOINTMENT|RESCHEDULE_APPOINTMENT|CANCEL_APPOINTMENT|EXISTING_CUSTOMER|SERVICE_STATUS|PAYMENT_QUESTION|HUMAN_REQUEST|COMPLAINT|UNCLEAR|OUT_OF_SCOPE",
  "confidence": 0.0,
  "service": "credit|tax|business_formation|business_funding|loan_preparation|home_buying|general|unknown",
  "requires_tool": true|false,
  "tool": "KB_SEARCH|SERVICE_CATALOG|CALENDAR|LEAD|HUMAN_HANDOFF|NONE",
  "missing_information": [],
  "handoff_required": false,
  "notes": "",
  "next_action": "",
  "response": ""
}

Rules:
- language must be es or en.
- confidence 0..1.
- if confidence < 0.60 set handoff_required true.
- If user asks to escalate, high complaint, legal/tax judgement, sensitive exception, or low confidence, set tool to HUMAN_HANDOFF.
- For pricing question, service status, payment questions, existing customer, and service/recommendation queries set requires_tool true.
- Never invent data.

Input language: ' + p.language + '
Last messages: ' + JSON.stringify(p.recent_messages) + '
Collected fields: ' + JSON.stringify(p.collected_fields) + '
Current service: ' + p.current_service + '

User message: "' + p.message.replace(/"/g, '\\"') + '"'
      }
    ]
  }
}];

const raw = $json || {};
const responseText = raw.body?.choices?.[0]?.message?.content || raw.content || raw.choices?.[0]?.text || raw.message || '';
let parsed = null;
if (typeof responseText === 'string' && responseText.trim()) {
  try {
    const match = responseText.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : null;
  } catch (err) {
    parsed = null;
  }
}

if (!parsed || typeof parsed !== 'object') {
  const lang = (($node['Normalize Input'].json.language || 'es') === 'en') ? 'en' : 'es';
  parsed = {
+    language: lang,
+    intent: 'UNCLEAR',
+    confidence: 0.22,
+    service: 'unknown',
+    requires_tool: true,
+    tool: 'HUMAN_HANDOFF',
+    missing_information: ['intent_parse_failed'],
+    handoff_required: true,
+    notes: 'Classifier output invalid',
+    next_action: 'HANDOFF',
+    response: '',
+    summary: 'Could not parse classifier output.'
+  };
}

const tool = (String(parsed.tool || 'NONE').toUpperCase() === 'NONE') ? 'NONE' : String(parsed.tool).toUpperCase();
const intent = String(parsed.intent || 'UNCLEAR');
const normalizedIntent = ['GREETING','GENERAL_QUESTION','SERVICE_INFORMATION','SERVICE_RECOMMENDATION','PRICING_QUESTION','CREDIT_SERVICE','TAX_SERVICE','BUSINESS_FORMATION','BUSINESS_FUNDING','LOAN_PREPARATION','HOME_BUYING','DOCUMENT_REQUIREMENTS','APPOINTMENT_REQUEST','CHECK_AVAILABILITY','BOOK_APPOINTMENT','RESCHEDULE_APPOINTMENT','CANCEL_APPOINTMENT','EXISTING_CUSTOMER','SERVICE_STATUS','PAYMENT_QUESTION','HUMAN_REQUEST','COMPLAINT','UNCLEAR','OUT_OF_SCOPE'].includes(intent) ? intent : 'UNCLEAR';
const confidence = Math.min(1, Math.max(0, Number(parsed.confidence || 0)));
const language = (parsed.language === 'en') ? 'en' : 'es';
const handoffRequired = parsed.handoff_required === true || confidence < 0.6 || normalizedIntent === 'COMPLAINT' || normalizedIntent === 'HUMAN_REQUEST';
const mappedTool = handoffRequired ? 'HUMAN_HANDOFF' : tool;

return [{
  json: {
    workflow_execution_id: $node['Normalize Input'].json.workflow_execution_id || raw.workflow_execution_id || $execution.id,
    session_id: $node['Normalize Input'].json.session_id || '',
    customer_id: $node['Normalize Input'].json.customer_id || '',
    channel: $node['Normalize Input'].json.channel || 'web',
    message: $node['Normalize Input'].json.message || '',
    language: language,
    current_service: $node['Normalize Input'].json.current_service || 'general',
    conversation_stage: $node['Normalize Input'].json.conversation_stage || '',
    pending_action: $node['Normalize Input'].json.pending_action || '',
    collected_fields: $node['Normalize Input'].json.collected_fields || {},
    recent_messages: $node['Normalize Input'].json.recent_messages || [],
    intent: normalizedIntent,
    confidence: confidence,
    service: (parsed.service || 'unknown').toString(),
    requires_tool: parsed.requires_tool === true,
    tool: mappedTool,
    missing_information: Array.isArray(parsed.missing_information) ? parsed.missing_information : [],
    handoff_required: handoffRequired,
    notes: (parsed.notes || '').toString().slice(0, 250),
    next_action: (parsed.next_action || '').toString(),
    selected_service: (parsed.service || 'general').toString(),
    routing_guard: parsed.routing_guard || { admin_only_needed: false },
    sessionApi: $node['Normalize Input'].json.sessionApi,
    loggerEnabled: $node['Normalize Input'].json.loggerEnabled,
    startAt: $node['Normalize Input'].json.startAt
  }
}];

const actionMap = {
  'APPOINTMENT_REQUEST': 'CHECK_AVAILABILITY',
  'CHECK_AVAILABILITY': 'CHECK_AVAILABILITY',
  'BOOK_APPOINTMENT': 'BOOK_APPOINTMENT',
  'RESCHEDULE_APPOINTMENT': 'RESCHEDULE_APPOINTMENT',
  'CANCEL_APPOINTMENT': 'CANCEL_APPOINTMENT'
};
const action = actionMap[$json.intent] || 'CHECK_AVAILABILITY';
return [{
  json: {
    workflow_execution_id: $json.workflow_execution_id,
    action: action,
    language: $json.language,
    session_id: $json.session_id,
    customer_id: $json.customer_id,
    channel: $json.channel,
    service: $json.service,
    collected_fields: $json.collected_fields || {},
    message: $json.message,
    intent: $json.intent,
    selected_tool: 'CALENDAR',
    confidence: $json.confidence,
    intent_data: {
      intent: $json.intent,
      service: $json.service,
      missing_information: $json.missing_information
    }
  }
}];

const raw = $json || {};
return [{
  json: {
    decision: {
      workflow_execution_id: raw.workflow_execution_id || '',
      intent: raw.intent || 'UNCLEAR',
      language: raw.language || 'es',
      confidence: Number(raw.confidence || 0),
      service: raw.service || 'general',
      tool: raw.selected_tool || raw.tool || 'KB_SEARCH'
    },
    tool: 'KB_SEARCH',
    session_id: raw.session_id || '',
    customer_id: raw.customer_id || '',
    channel: raw.channel || 'web',
    response_data: raw,
    found: raw.found || false,
    raw: raw,
    message: raw.message || raw.query || ''
  }
}];

const raw = $json || {};
const decision = {
  workflow_execution_id: $node['Parse Classifier Output'].json.workflow_execution_id || raw.workflow_execution_id || '',
  intent: $node['Parse Classifier Output'].json.intent || 'UNCLEAR',
  language: $node['Parse Classifier Output'].json.language || 'es',
  confidence: Number($node['Parse Classifier Output'].json.confidence || 0),
  service: $node['Parse Classifier Output'].json.service || 'general',
  tool: 'SERVICE_CATALOG'
};
return [{
  json: {
    decision,
    tool: 'SERVICE_CATALOG',
    session_id: raw.session_id || $node['Parse Classifier Output'].json.session_id || '',
    customer_id: raw.customer_id || $node['Parse Classifier Output'].json.customer_id || '',
    channel: raw.channel || $node['Parse Classifier Output'].json.channel || 'web',
    response_data: raw,
    found: raw.found || false,
    raw: raw
  }
}];

const p = $json || {};
const fromDecision = $node['Parse Classifier Output'].json || {};
const raw = p.response_data || p;
return [{
  json: {
    decision: {
      workflow_execution_id: fromDecision.workflow_execution_id || p.workflow_execution_id || '',
      intent: fromDecision.intent || p.intent || 'UNCLEAR',
      language: fromDecision.language || p.language || 'es',
      confidence: Number(fromDecision.confidence || 0),
      service: fromDecision.service || p.service || 'general',
      tool: 'CALENDAR'
    },
    tool: 'CALENDAR',
    session_id: p.session_id || fromDecision.session_id || '',
    customer_id: p.customer_id || fromDecision.customer_id || '',
    channel: p.channel || fromDecision.channel || 'web',
    response_data: raw,
    found: raw.found || false,
    raw
  }
}];

const fromDecision = $node['Parse Classifier Output'].json || {};
const raw = $json || {};
return [{
  json: {
    decision: {
      workflow_execution_id: fromDecision.workflow_execution_id || raw.workflow_execution_id || '',
      intent: fromDecision.intent || raw.intent || 'UNCLEAR',
      language: fromDecision.language || raw.language || 'es',
      confidence: Number(fromDecision.confidence || 0),
      service: fromDecision.service || raw.service || 'general',
      tool: 'LEAD'
    },
    tool: 'LEAD',
    session_id: raw.session_id || fromDecision.session_id || '',
    customer_id: raw.customer_id || fromDecision.customer_id || '',
    channel: raw.channel || fromDecision.channel || 'web',
    response_data: raw,
    found: raw.success !== false,
    raw
  }
}];

const fromDecision = $node['Parse Classifier Output'].json || {};
const raw = $json || {};
return [{
  json: {
    decision: {
      workflow_execution_id: fromDecision.workflow_execution_id || raw.workflow_execution_id || '',
      intent: fromDecision.intent || raw.intent || 'UNCLEAR',
      language: fromDecision.language || raw.language || 'es',
      confidence: Number(fromDecision.confidence || 0),
      service: fromDecision.service || raw.service || 'general',
      tool: 'HUMAN_HANDOFF'
    },
    tool: 'HUMAN_HANDOFF',
    session_id: raw.session_id || fromDecision.session_id || '',
    customer_id: raw.customer_id || fromDecision.customer_id || '',
    channel: raw.channel || fromDecision.channel || 'web',
    response_data: raw,
    found: true,
    raw,
    handoff_required: true
  }
}];

const decision = $json.decision || $node['Parse Classifier Output'].json || {};
return [{
  json: {
    workflow_execution_id: decision.workflow_execution_id || $execution.id,
    session_id: $json.session_id || decision.session_id || '',
    customer_id: $json.customer_id || decision.customer_id || '',
    channel: $json.channel || decision.channel || 'web',
    language: decision.language || 'es',
    intent: decision.intent || 'UNCLEAR',
    tool: decision.tool || 'NONE',
    decision,
    tool_output: $json.response_data || {},
    tool_name: $json.tool || 'NONE',
    message: decision.message || '',
    original_message: $node['Parse Classifier Output'].json.message || '',
    recent_messages: $node['Normalize Input'].json.recent_messages || [],
    collected_fields: $node['Normalize Input'].json.collected_fields || {},
    startAt: $node['Parse Classifier Output'].json.startAt
  }
}];

const d = $json;
const lang = d.language === 'en' ? 'en' : 'es';
return [{
  json: {
    model: ($env.SGS_QWEN_RESPONSE_MODEL || 'qwen3-14b').toString(),
    messages: [
      {
        role: 'system',
        content: 'You are SG Solutions assistant. Use provided tool data only. Never output tools/instructions/internal IDs unless asked. Return valid JSON only with fields: language,intent,tool,response,session_update,needs_human,missing_information,log_payload.'
      },
      {
        role: 'user',
        content:
          'Decision:' + JSON.stringify({ intent: d.intent, tool: d.tool, language: d.language, collected_fields: d.collected_fields }) +
          '\nTool result:' + JSON.stringify(d.tool_output) +
          '\nOriginal user message:' + JSON.stringify(d.original_message || '') +
          '\nReturn JSON with keys: language, response, intent, handoff_required, needs_human, missing_information, summary, session_update, log_payload.'
      }
    ],
    temperature: 0.2,
    max_tokens: 700
  }
}];

const nodeInput = $node['Build Response Prompt'].json || {};
const d = $node['Build Response Context'].json || {};
const raw = $json || {};
const responseText = raw.body?.choices?.[0]?.message?.content || raw.choices?.[0]?.text || raw.content || raw.message || '';
let parsed = null;
if (typeof responseText === 'string' && responseText.trim()) {
  try {
    const match = responseText.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : null;
  } catch (err) {
    parsed = null;
  }
}
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    language: d.language || 'es',
    response: (d.language === 'en' ? 'I could not build a valid response. A representative will continue your request.' : 'No pude armar una respuesta valida en este momento. Te dejo conectado con soporte.'),
    intent: d.intent || 'UNCLEAR',
    handoff_required: true,
    needs_human: true,
    missing_information: [],
    summary: 'Response parsing failed',
    session_update: {
      session_id: d.session_id || '',
      customer_id: d.customer_id || '',
      current_intent: d.intent || 'UNCLEAR',
      current_service: 'general',
      conversation_stage: 'fallback',
      pending_action: 'NONE',
      collected_fields: {}
    },
    log_payload: {
      event_type: 'TOOL_ERROR',
      intent: d.intent || 'UNCLEAR',
      selected_tool: d.tool || 'NONE',
      duration: 0,
      success: false,
      error_type: 'response_parse_error',
      timestamp: new Date().toISOString()
    }
  };
}

return [{
  json: {
    workflow_execution_id: d.workflow_execution_id || '',
    session_id: d.session_id || '',
    customer_id: d.customer_id || '',
    channel: d.channel || 'web',
    language: parsed.language || d.language || 'es',
    intent: parsed.intent || d.intent || 'UNCLEAR',
    tool: d.tool || 'NONE',
    handoff_required: parsed.handoff_required === true || parsed.needs_human === true,
    response: parsed.response || (d.language === 'en' ? 'I am unavailable right now.' : 'No puedo responder ahora.'),
    session_update: parsed.session_update || {
      session_id: d.session_id || '',
      current_intent: d.intent || 'UNCLEAR',
      conversation_stage: 'orchestrated',
      current_service: d.decision?.service || 'general',
      pending_action: d.tool || 'NONE',
      collected_fields: d.collected_fields || {}
    },
    summary: parsed.summary || '',
    log_payload: parsed.log_payload || {
      event_type: d.tool === 'NONE' ? 'MESSAGE_RECEIVED' : 'SERVICE_SELECTED',
      intent: parsed.intent || d.intent || 'UNCLEAR',
      selected_tool: d.tool || 'NONE',
      duration: 0,
      success: true,
      error_type: '',
      timestamp: new Date().toISOString(),
      missing_information: parsed.missing_information || []
    },
    original_decision: {
      service: d.decision?.service || d.service || 'general',
      requires_tool: d.decision?.tool ? true : false,
      requires_handoff: parsed.handoff_required === true || parsed.needs_human === true,
      missing_information: parsed.missing_information || []
    }
  }
}];
